CREATE TABLE IF NOT EXISTS gis_phase362_certification_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, authoritative_source_id TEXT NOT NULL, feature_id TEXT NOT NULL, event_type TEXT NOT NULL, event_hash TEXT NOT NULL, previous_event_hash TEXT, payload JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,authoritative_source_id,feature_id,event_type,event_hash)); CREATE INDEX IF NOT EXISTS idx_phase362_feature ON gis_phase362_certification_events(certification_version,authoritative_source_id,feature_id); CREATE TABLE IF NOT EXISTS gis_phase362_certification_state (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, authoritative_source_id TEXT NOT NULL, feature_id TEXT NOT NULL, state TEXT NOT NULL, current_hash TEXT NOT NULL, revoked_reason TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,authoritative_source_id,feature_id));